import sys

import rclpy
from std_srvs.srv import SetBool

from ros2cli.node.direct import add_arguments
from ros2cli.node.strategy import NodeStrategy
from ros2cli.verb import VerbExtension

from ros2controlcli.api import add_controller_mgr_parsers


class AutoSwitchModeVerb(VerbExtension):
    """Enable or disable auto switch mode for controller manager."""

    def add_arguments(self, parser, cli_name):
        add_arguments(parser)
        add_controller_mgr_parsers(parser)
        group = parser.add_mutually_exclusive_group(required=True)
        group.add_argument(
            "--enable",
            action="store_true",
            help="Enable auto switch mode",
        )
        group.add_argument(
            "--disable",
            action="store_true",
            help="Disable auto switch mode",
        )

    def main(self, *, args):
        with NodeStrategy(args).direct_node as node:
            cm = args.controller_manager.strip("/")
            service_name = f"/{cm}/auto_switch_mode"
            client = node.create_client(SetBool, service_name)

            if not client.wait_for_service(timeout_sec=5.0):
                print(f"Service {service_name} not available", file=sys.stderr)
                return 1

            request = SetBool.Request()
            request.data = args.enable

            future = client.call_async(request)
            rclpy.spin_until_future_complete(node, future, timeout_sec=5.0)

            if future.result() is not None:
                response = future.result()
                if response.success:
                    print(f"Success: {response.message}")
                    return 0
                else:
                    print(f"Failed: {response.message}", file=sys.stderr)
                    return 1
            else:
                print("Service call failed", file=sys.stderr)
                return 1
